"""numbering.xml: list definitions, counters and label formatting."""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Optional

from ..oxml import find, findall, get, int_of, on_off, val
from .props import ParaProps, RunProps, parse_ppr, parse_rpr

# Symbol / Wingdings code points used by Word's default bullets, mapped to
# Unicode look-alikes so we do not depend on those fonts being installed.
SYMBOL_BULLETS = {
    '': '•',   # Symbol filled round bullet
    '': '▪',   # Wingdings filled square
    '': '➢',   # Wingdings arrowhead
    '': '✓',   # Wingdings check mark
    '': '❑',   # Wingdings shadowed square
    '': '■',   # Wingdings black square
    '': '❖',   # Wingdings diamond
    '': '▫',
    '': '➤',
    '': '–',
    '': '⇒',
    'o': '○',
}

ROMAN = ((1000, 'm'), (900, 'cm'), (500, 'd'), (400, 'cd'), (100, 'c'),
         (90, 'xc'), (50, 'l'), (40, 'xl'), (10, 'x'), (9, 'ix'),
         (5, 'v'), (4, 'iv'), (1, 'i'))

ONES = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight',
        'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen',
        'sixteen', 'seventeen', 'eighteen', 'nineteen']
TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy',
        'eighty', 'ninety']
ORDINALS = {'one': 'first', 'two': 'second', 'three': 'third', 'five': 'fifth',
            'eight': 'eighth', 'nine': 'ninth', 'twelve': 'twelfth'}


def to_roman(n: int) -> str:
    if n <= 0:
        return str(n)
    out = []
    for value, numeral in ROMAN:
        while n >= value:
            out.append(numeral)
            n -= value
    return ''.join(out)


def to_letter(n: int) -> str:
    """1 -> a, 26 -> z, 27 -> aa (Word repeats the letter rather than base-26)."""
    if n <= 0:
        return str(n)
    index = (n - 1) % 26
    repeat = (n - 1) // 26 + 1
    return chr(ord('a') + index) * repeat


def to_words(n: int) -> str:
    if n < 0:
        return str(n)
    if n < 20:
        return ONES[n]
    if n < 100:
        rest = n % 10
        return TENS[n // 10] + ('-' + ONES[rest] if rest else '')
    if n < 1000:
        rest = n % 100
        return ONES[n // 100] + ' hundred' + (' ' + to_words(rest) if rest else '')
    if n < 1000000:
        rest = n % 1000
        return to_words(n // 1000) + ' thousand' + (' ' + to_words(rest) if rest else '')
    return str(n)


def to_ordinal_words(n: int) -> str:
    words = to_words(n)
    head, _, tail = words.rpartition(' ')
    last = tail or words
    base, _, piece = last.rpartition('-')
    piece = piece or last
    if piece in ORDINALS:
        converted = ORDINALS[piece]
    elif piece.endswith('y'):
        converted = piece[:-1] + 'ieth'
    else:
        converted = piece + 'th'
    if base and base != piece:
        converted = base + '-' + converted
    return (head + ' ' + converted).strip() if head else converted


def to_ordinal(n: int) -> str:
    if 10 <= n % 100 <= 20:
        suffix = 'th'
    else:
        suffix = {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th')
    return '%d%s' % (n, suffix)


def format_number(n: int, fmt: str) -> str:
    fmt = fmt or 'decimal'
    if fmt == 'decimal':
        return str(n)
    if fmt == 'decimalZero':
        return '%02d' % n
    if fmt == 'upperRoman':
        return to_roman(n).upper()
    if fmt == 'lowerRoman':
        return to_roman(n)
    if fmt == 'upperLetter':
        return to_letter(n).upper()
    if fmt == 'lowerLetter':
        return to_letter(n)
    if fmt == 'ordinal':
        return to_ordinal(n)
    if fmt == 'cardinalText':
        return to_words(n).capitalize()
    if fmt == 'ordinalText':
        return to_ordinal_words(n).capitalize()
    if fmt == 'decimalEnclosedCircle' and 1 <= n <= 20:
        return chr(0x2460 + n - 1)
    if fmt == 'decimalEnclosedParen' and 1 <= n <= 20:
        return chr(0x2474 + n - 1)
    if fmt in ('none',):
        return ''
    return str(n)


@dataclass
class Level:
    ilvl: int = 0
    start: int = 1
    num_fmt: str = 'decimal'
    lvl_text: str = '%1.'
    suffix: str = 'tab'
    jc: str = 'left'
    is_lgl: bool = False
    restart: Optional[int] = None
    pstyle: Optional[str] = None
    ppr: ParaProps = field(default_factory=ParaProps)
    rpr: RunProps = field(default_factory=RunProps)
    font: Optional[str] = None


def _parse_level(el) -> Level:
    ilvl = int_of(get(el, 'w:ilvl'), 0)
    rpr = parse_rpr(find(el, 'w:rPr'))
    return Level(
        ilvl=ilvl,
        start=int_of(val(find(el, 'w:start')), 1),
        num_fmt=val(find(el, 'w:numFmt'), 'decimal') or 'decimal',
        lvl_text=val(find(el, 'w:lvlText'), '') or '',
        suffix=val(find(el, 'w:suff'), 'tab') or 'tab',
        jc=val(find(el, 'w:lvlJc'), 'left') or 'left',
        is_lgl=bool(on_off(find(el, 'w:isLgl'), True)),
        restart=int_of(val(find(el, 'w:lvlRestart'))),
        pstyle=val(find(el, 'w:pStyle')),
        ppr=parse_ppr(find(el, 'w:pPr')),
        rpr=rpr,
        font=rpr.font_ascii,
    )


class Numbering:
    """Numbering definitions plus the running counters for one render pass."""

    def __init__(self, root=None, stylesheet=None):
        self.abstract: dict[int, dict[int, Level]] = {}
        self.abstract_style_link: dict[int, str] = {}
        self.nums: dict[int, int] = {}
        self.overrides: dict[int, dict[int, Level]] = {}
        self.start_overrides: dict[int, dict[int, int]] = {}
        self.stylesheet = stylesheet
        self._counters: dict[tuple, list] = {}
        if root is not None:
            self._load(root)

    def _load(self, root):
        for el in findall(root, 'w:abstractNum'):
            aid = int_of(get(el, 'w:abstractNumId'))
            if aid is None:
                continue
            levels = {}
            for lvl_el in findall(el, 'w:lvl'):
                lvl = _parse_level(lvl_el)
                levels[lvl.ilvl] = lvl
            self.abstract[aid] = levels
            link = val(find(el, 'w:numStyleLink'))
            if link:
                self.abstract_style_link[aid] = link
        for el in findall(root, 'w:num'):
            nid = int_of(get(el, 'w:numId'))
            if nid is None:
                continue
            aid = int_of(val(find(el, 'w:abstractNumId')))
            if aid is not None:
                self.nums[nid] = aid
            for ov in findall(el, 'w:lvlOverride'):
                ilvl = int_of(get(ov, 'w:ilvl'), 0)
                start = int_of(val(find(ov, 'w:startOverride')))
                if start is not None:
                    self.start_overrides.setdefault(nid, {})[ilvl] = start
                lvl_el = find(ov, 'w:lvl')
                if lvl_el is not None:
                    lvl = _parse_level(lvl_el)
                    lvl.ilvl = ilvl
                    self.overrides.setdefault(nid, {})[ilvl] = lvl

    # -- definition lookup --------------------------------------------------
    def abstract_id(self, num_id) -> Optional[int]:
        aid = self.nums.get(num_id)
        seen = set()
        while aid is not None and aid in self.abstract_style_link and aid not in seen:
            seen.add(aid)
            style_id = self.abstract_style_link[aid]
            linked = self._num_id_for_style(style_id)
            if linked is None:
                break
            aid = self.nums.get(linked)
        return aid

    def _num_id_for_style(self, style_id):
        if self.stylesheet is None:
            return None
        style = self.stylesheet.get(style_id)
        if style is None:
            return None
        return style.ppr.num_id

    def level(self, num_id, ilvl) -> Optional[Level]:
        if num_id is None:
            return None
        override = self.overrides.get(num_id, {}).get(ilvl)
        if override is not None:
            return override
        aid = self.abstract_id(num_id)
        if aid is None:
            return None
        levels = self.abstract.get(aid) or {}
        lvl = levels.get(ilvl)
        if lvl is None and levels:
            lvl = levels.get(min(levels))
        return lvl

    def is_bullet(self, num_id, ilvl) -> bool:
        lvl = self.level(num_id, ilvl)
        return bool(lvl) and lvl.num_fmt == 'bullet'

    # -- counters -----------------------------------------------------------
    def reset(self):
        self._counters.clear()

    def _key(self, num_id):
        aid = self.abstract_id(num_id)
        return ('a', aid) if aid is not None else ('n', num_id)

    def next_label(self, num_id, ilvl):
        """Advance the counters and return ``(text, Level)`` for a paragraph."""
        lvl = self.level(num_id, ilvl)
        if lvl is None:
            return None, None
        key = self._key(num_id)
        counters = self._counters.get(key)
        if counters is None:
            counters = [None] * 9
            self._counters[key] = counters
        if counters[ilvl] is None:
            counters[ilvl] = self._start_of(num_id, ilvl) - 1
        counters[ilvl] += 1
        for deeper in range(ilvl + 1, 9):
            deeper_lvl = self.level(num_id, deeper)
            if deeper_lvl is not None and deeper_lvl.restart == 0:
                continue
            counters[deeper] = None
        if lvl.num_fmt == 'none':
            return '', lvl
        return self._format_label(num_id, ilvl, lvl, counters), lvl

    def _start_of(self, num_id, ilvl) -> int:
        start = self.start_overrides.get(num_id, {}).get(ilvl)
        if start is not None:
            return start
        lvl = self.level(num_id, ilvl)
        return lvl.start if lvl else 1

    def peek_counters(self, num_id):
        return list(self._counters.get(self._key(num_id), [None] * 9))

    def _format_label(self, num_id, ilvl, lvl, counters) -> str:
        text = lvl.lvl_text or ''
        if lvl.num_fmt == 'bullet':
            return ''.join(SYMBOL_BULLETS.get(ch, ch) for ch in text)

        def repl(match):
            index = int(match.group(1)) - 1
            if index < 0 or index > 8:
                return match.group(0)
            value = counters[index]
            if value is None:
                value = self._start_of(num_id, index)
            fmt = 'decimal'
            if index == ilvl:
                fmt = lvl.num_fmt
            else:
                other = self.level(num_id, index)
                if other is not None:
                    fmt = 'decimal' if lvl.is_lgl else other.num_fmt
            return format_number(value, fmt)

        return re.sub(r'%(\d)', repl, text)
